insert into public.page_blocks (key, page, type, value_he, value_en, value_ru, value_fr, image_path, image_alt, status, sort_order) values
  ('ap_p1', 'app', 'text', 'בסיסי', 'Basic', 'Базовый', 'Essentiel', null, null, 'published', 3),
  ('hero_location', 'home', 'text', 'הרצליה ישראל | HERZLIYA ISRAEL', 'הרצליה ישראל | HERZLIYA ISRAEL', 'הרצליה ישראל | HERZLIYA ISRAEL', 'הרצליה ישראל | HERZLIYA ISRAEL', null, null, 'published', 3),
  ('ab2_p2', 'about', 'rich', 'מייסד הקבוצה והשותפים למלאכה מביאים איתם ניסיון רב שנים מאז <span class="yr-sp">1995</span> ועד היום שנבנה מתוך עשייה אמיתית בשטח, הכישורים והיכולות אשר אותם צברו. מתוך הניסיון הזה נולד חזון אחד לאחד את שירותי הבנייה והעיצובים תחת קורת גג אחת שמלווה את כל שלבי הפרויקט משלב הרעיון, דרך התכנון ההנדסי הבנייה ועד לשלב המפתח.', 'The founder of the group and his partners in the craft bring many years of experience, since <span class="yr-sp">1995</span> to this day, built from real work in the field, together with the skills and abilities they have gained. From this experience was born a single vision: to unite construction and design services under one roof that accompanies every stage of the project, from the initial idea, through engineering design and construction, to the handover of the keys.', 'Основатель группы и его партнёры по ремеслу привносят многолетний опыт — с <span class="yr-sp">1995</span> года и по сегодняшний день, — накопленный в реальной работе на объектах, а также приобретённые навыки и возможности. Из этого опыта родилось единое видение: объединить услуги по строительству и дизайну под одной крышей, которая сопровождает все этапы проекта — от идеи через инженерное проектирование и строительство до передачи ключей.', 'Le fondateur du groupe et ses partenaires apportent de nombreuses années d''expérience, depuis <span class="yr-sp">1995</span> jusqu''à aujourd''hui, bâtie sur un véritable travail de terrain, ainsi que les compétences et les capacités qu''ils ont acquises. De cette expérience est née une vision unique : réunir les services de construction et de design sous un même toit, qui accompagne toutes les étapes du projet, de l''idée à la conception technique, puis à la construction jusqu''à la remise des clés.', null, null, 'published', 4),
  ('tm_h2', 'teams', 'text', 'אנשי משרד', 'Office Staff', 'Офисные сотрудники', 'Équipe de bureau', null, null, 'published', 3),
  ('d3_extra', 'real-estate', 'text', 'אתם זה אנחנו !  ואנחנו זה אתם !  משפחה !', 'You are us! And we are you! Family!', 'Вы — это мы! А мы — это вы! Семья!', 'Vous, c’est nous ! Et nous, c’est vous ! Une famille !', null, null, 'published', 3),
  ('info_l3', 'info', 'text', 'חשבנו בשבילכם על הכל...', 'We thought of everything for you...', 'Мы подумали для вас обо всём...', 'Nous avons pensé à tout pour vous...', null, null, 'published', 4),
  ('f_last', 'contact', 'text', 'משפחה', 'Last name', 'Фамилия', 'Nom', null, null, 'published', 3),
  ('svc_back', 'construction', 'text', 'חזרה לכל השירותים', 'Back to all services', 'Назад ко всем услугам', 'Retour à tous les services', null, null, 'published', 4),
  ('pm_gallery', 'project', 'text', 'גלריית הפרויקט', 'Project gallery', 'Галерея проекта', 'Galerie du projet', null, null, 'published', 3),
  ('sector_private', 'projects', 'text', 'מגזר פרטי', 'Private sector', 'Частный сектор', 'Secteur privé', null, null, 'published', 3),
  ('ip_name', 'in-progress', 'text', 'שם הפרויקט', 'Project name', 'Название проекта', 'Nom du projet', null, null, 'published', 4),
  ('car_r4', 'careers', 'text', 'אנשי משרד ושירות', 'Office & Service Staff', 'Офис и сервис', 'Personnel de bureau et de service', null, null, 'published', 4),
  ('tn_perk2', 'tenders', 'text', 'מועדי פתיחה והגשה', 'Opening and submission dates', 'Даты открытия и подачи', 'Dates d’ouverture et de dépôt', null, null, 'published', 4),
  ('ap_price', 'app', 'text', 'המחיר יותאם לנכס', 'Price tailored to your property', 'Цена подбирается под объект', 'Prix adapté à votre bien', null, null, 'published', 4),
  ('ab2_p3', 'about', 'text', 'כך נולד הרעיון לאחד את הבנייה והעיצובים לבית אחד, שנותן מענה מלא לכל פרויקט.', 'This is how the idea was born to unite construction and design in one house, giving a complete answer to every project.', 'Так родилась идея объединить строительство и дизайн в одном доме, который даёт полный ответ для каждого проекта.', 'C''est ainsi qu''est née l''idée d''unir construction et design dans une seule maison, qui apporte une réponse complète à chaque projet.', null, null, 'published', 5),
  ('tm_h3', 'teams', 'text', 'אנשי שטח', 'Field Teams', 'Полевые команды', 'Équipes de terrain', null, null, 'published', 4),
