  ('tn_forgot_sent', 'tenders', 'text', 'אם הקוד קיים ויש לו מייל שמור, נשלחה אליו סיסמה זמנית', 'If the code exists and has a saved email, a temporary password was sent to it', 'Если код существует и для него сохранена почта, на неё отправлен временный пароль', 'Si le code existe et qu’un e-mail est enregistré, un mot de passe temporaire lui a été envoyé', null, null, 'published', 11),
  ('ap_p2_l2', 'app', 'text', 'מוקד שירות מורחב', 'Extended service center', 'Расширенный сервисный центр', 'Centre de service étendu', null, null, 'published', 11),
  ('ab2_p9', 'about', 'text', 'באמצעות חלוקת אחריות מדויקת, ניהול מקצועי, פיקוח ותיאום בין כלל הגורמים, אנו מבטיחים תהליך עבודה מסודר, יעיל ומותאם לאופי הפרויקט ולצורכי הלקוח', 'Through a precise division of responsibility, professional management, supervision and coordination between all parties, we ensure an orderly, efficient work process adapted to the nature of the project and the client''s needs.', 'Благодаря чёткому распределению ответственности, профессиональному управлению, надзору и координации между всеми сторонами мы обеспечиваем упорядоченный, эффективный рабочий процесс, адаптированный к характеру проекта и потребностям клиента.', 'Grâce à une répartition précise des responsabilités, une gestion professionnelle, une supervision et une coordination entre toutes les parties, nous garantissons un processus de travail ordonné, efficace et adapté à la nature du projet et aux besoins du client.', null, null, 'published', 13),
  ('svc_b1', 'services', 'text', 'אבטחה סגורה במעגל סגור 24/7', 'Closed security, CCTV 24/7', 'Закрытая охрана, видеонаблюдение 24/7', 'Sécurité fermée, circuit fermé 24/7', null, null, 'published', 4),
  ('c14s', 'planning', 'text', 'השלב הכי כיפי והמאתגר בפרויקט', 'The most fun and challenging stage of the project', 'Самый приятный и сложный этап проекта', 'L’étape la plus amusante et la plus stimulante du projet', null, null, 'published', 10),
  ('c25s', 'infrastructure', 'text', 'הכל מתחיל ביסודות טובים', 'Everything starts with good foundations', 'Всё начинается с хорошего фундамента', 'Tout commence par de bonnes fondations', null, null, 'published', 2),
  ('pt_slogan_soon', 'partners', 'text', 'סלוגן יתווסף בקרוב', 'Slogan coming soon', 'Слоган скоро появится', 'Slogan à venir', null, null, 'published', 9),
  ('car_r3s', 'careers', 'text', 'תכנון והנדסה ברמה הגבוהה ביותר', 'Planning and engineering at the highest level', 'Проектирование и инженерия высочайшего уровня', 'Conception et ingénierie au plus haut niveau', null, null, 'published', 10),
  ('tn_forgot_office', 'tenders', 'text', 'אם לא קיבלתם מייל, פנו למשרד', 'If you did not get an email, contact the office', 'Если письмо не пришло, обратитесь в офис', 'Si vous n’avez pas reçu l’e-mail, contactez le bureau', null, null, 'published', 12),
  ('ap_p2_l3', 'app', 'text', 'אחזקה שוטפת של מערכות', 'Ongoing systems maintenance', 'Текущее обслуживание систем', 'Entretien courant des systèmes', null, null, 'published', 12),
  ('ab2_p10', 'about', 'text', 'בכל פרויקט, לכל שלב יש את המומחיות שלו.', 'In every project, each stage has its own expertise.', 'В каждом проекте у каждого этапа есть своя экспертиза.', 'Dans chaque projet, chaque étape a son expertise.', null, null, 'published', 14),
  ('c24', 'planning', 'text', 'ליקויי בנייה', 'Construction Defects', 'Строительные дефекты', 'Défauts de construction', null, null, 'published', 11),
  ('c26', 'infrastructure', 'text', 'אספלט וכבישים', 'Asphalt & Roads', 'Асфальт и дороги', 'Asphalte et routes', null, null, 'published', 3),
  ('nav_gallery', 'contact', 'text', 'גלריה בנייה ועיצובים', 'Gallery — Building & Design', 'Галерея — строительство и дизайн', 'Galerie — construction & design', null, null, 'published', 9),
  ('tn_login_btn', 'tenders', 'text', 'כניסה', 'Sign in', 'Войти', 'Se connecter', null, null, 'published', 13),
  ('ap_p2_l4', 'app', 'text', 'עדיפות בטיפול', 'Priority handling', 'Приоритетное обслуживание', 'Traitement prioritaire', null, null, 'published', 13),
  ('ab2_p11', 'about', 'text', 'הלקוח נהנה ממומחיות ייעודית בכל שלב, לצד ניהול מתואם ואחריות כוללת לאורך הפרויקט.', 'The client enjoys dedicated expertise at every stage, alongside coordinated management and overall responsibility throughout the project.', 'Клиент получает специализированную экспертизу на каждом этапе, а также скоординированное управление и общую ответственность на протяжении всего проекта.', 'Le client bénéficie d''une expertise dédiée à chaque étape, ainsi que d''une gestion coordonnée et d''une responsabilité globale tout au long du projet.', null, null, 'published', 15)
insert into public.page_blocks (key, page, type, value_he, value_en, value_ru, value_fr, image_path, image_alt, status, sort_order) values
  ('c24s', 'planning', 'text', 'נתקן את זה !', 'We will fix it!', 'Мы это исправим!', 'Nous allons le réparer !', null, null, 'published', 12),
  ('c26s', 'infrastructure', 'text', 'גם הכבשים צריכים להיות מושלמים', 'The roads must be perfect too', 'Дороги тоже должны быть идеальными', 'Les routes aussi doivent être parfaites', null, null, 'published', 4),
