  ('car_r2s', 'shared', 'text', 'בעלי מקצוע מנוסים לעבודה משותפת לאורך זמן', 'Experienced professionals for long-term cooperation', 'Опытные мастера для долгосрочного сотрудничества', 'Des professionnels expérimentés pour une collaboration durable', null, null, 'published', 17),
  ('car_f_area_ph', 'shared', 'text', 'לדוגמה: השרון, מרכז', 'e.g. Sharon, Center', 'например: Шарон, Центр', 'ex. : Sharon, Centre', null, null, 'published', 18),
  ('car_req', 'shared', 'text', 'דרישות התפקיד', 'Requirements', 'Требования', 'Exigences du poste', null, null, 'published', 19),
  ('car_adv', 'shared', 'text', 'יתרון', 'An advantage', 'Преимуществом будет', 'Un atout', null, null, 'published', 20),
  ('car_offer', 'shared', 'text', 'מה אנחנו מציעים', 'What we offer', 'Что мы предлагаем', 'Ce que nous offrons', null, null, 'published', 21),
  ('car_thanks', 'shared', 'text', 'תודה! קורות החיים התקבלו לתפקיד {role}. נחזור אליכם בהקדם.', 'Thank you! Your CV for the {role} role has been received. We will get back to you soon.', 'Спасибо! Ваше резюме на должность «{role}» получено. Мы скоро свяжемся с вами.', 'Merci ! Votre CV pour le poste « {role} » a bien été reçu. Nous vous recontacterons rapidement.', null, null, 'published', 22),
  ('car_cv', 'shared', 'text', 'העלאת קורות חיים', 'Upload your CV', 'Загрузите резюме', 'Téléchargez votre CV', null, null, 'published', 23),
  ('car_cv_hint', 'shared', 'text', 'גררו לכאן קובץ או לחצו לבחירה', 'Drag a file here or click to choose', 'Перетащите файл сюда или нажмите, чтобы выбрать', 'Glissez un fichier ici ou cliquez pour choisir', null, null, 'published', 24),
  ('car_cv_types', 'shared', 'text', 'PDF או Word · עד 5MB', 'PDF or Word · up to 5MB', 'PDF или Word · до 5 МБ', 'PDF ou Word · 5 Mo max.', null, null, 'published', 25),
  ('car_cv_remove', 'shared', 'text', 'הסרת הקובץ', 'Remove file', 'Удалить файл', 'Supprimer le fichier', null, null, 'published', 26),
