  ('car_cv_err_size', 'shared', 'text', 'הקובץ גדול מ-5MB', 'The file is larger than 5MB', 'Файл больше 5 МБ', 'Le fichier dépasse 5 Mo', null, null, 'published', 28),
  ('car_cv_req', 'shared', 'text', 'יש לצרף קובץ קורות חיים', 'Please attach your CV', 'Пожалуйста, приложите резюме', 'Veuillez joindre votre CV', null, null, 'published', 29),
