insert into public.page_blocks (key, page, type, value_he, value_en, value_ru, value_fr, image_path, image_alt, status, sort_order) values
  ('p9', 'shared', 'text', 'מבנים מיוחדים', 'Special Buildings', 'Особые здания', 'Bâtiments spéciaux', null, null, 'published', 111),
  ('info_l4', 'shared', 'text', 'מומלץ לשמוע ברמקול וליהנות מחוויית צפייה אתגרית בידע והכוונה לצרכים שלכם.     שותפים למבנה שלכם !', 'We recommend listening on a speaker and enjoying a challenging viewing experience of knowledge and guidance for your needs. Partners of your building!', 'Рекомендуем слушать через динамик и наслаждаться познавательным просмотром с ориентацией на ваши потребности. Партнёры вашего здания!', 'Nous recommandons d’écouter au haut-parleur et de profiter d’une expérience de visionnage stimulante, riche en savoir et en conseils adaptés à vos besoins. Partenaires de votre bâtiment !', null, null, 'published', 112),
  ('info_l5', 'shared', 'text', 'האתר מושמע בקריינות והסברה לבונה ולמשפץ', 'The site is narrated with voice-over and explanations for the builder and renovator', 'Сайт озвучен дикторским сопровождением и пояснениями для строящего и ремонтирующего', 'Le site est commenté en voix off avec des explications pour le bâtisseur et le rénovateur', null, null, 'published', 113),
